The correct structure for the IMAGE_BASE_RELOCATION block is:

<pre><code>DWORD   VirtualAddress;
DWORD   SizeOfBlock; // size of current relocation, including the IMAGE_BASE_RELOCATION header
WORD    TypeOffset[1]; // variable number of entries, depending on SizeOfBlock
</code></pre>

The SizeOfBlock field includes the size of the IMAGE_BASE_RELOCATION header itself, so to calculate the number of TypeOffset entries, you need to subtract the header size and divide by the size of a WORD.

In your code, the calculation for the entry pointer is incorrect. Instead of adding sizeof(IMAGE_BASE_RELOCATION) to the baseRelocation pointer, you should add the current position within the block, which is j * sizeof(WORD) + sizeof(IMAGE_BASE_RELOCATION).

Here's the corrected code:

<pre><code>DWORD baseRelocationSize = imageNtHeaders-&gt;OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].Size;
unsigned int baseRelocationCount = baseRelocationSize / sizeof(IMAGE_BASE_RELOCATION);
DWORD baseDelta = (DWORD_PTR)moduleBase - (DWORD_PTR)imageNtHeaders-&gt;OptionalHeader.ImageBase;

IMAGE_BASE_RELOCATION* baseRelocation = (IMAGE_BASE_RELOCATION*)((DWORD_PTR)moduleBase + (DWORD_PTR)imageNtHeaders-&gt;OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress);

for(unsigned int i = 0; i != baseRelocationCount; ++i)
{
    unsigned int entryCount = (baseRelocation-&gt;SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(WORD);
    WORD* entry = (WORD*)(baseRelocation + 1);

    for(unsigned int j = 0; j != entryCount; ++j)
    {
        if((*entry &gt;&gt; 12) &amp; IMAGE_REL_BASED_HIGHLOW)
        {
            DWORD* pdw = (PDWORD)((DWORD_PTR)moduleBase + (DWORD_PTR)baseRelocation-&gt;VirtualAddress + (*entry &amp; 0xfff));
            (*pdw) += baseDelta;
        }

        entry++;
    }

    baseRelocation = (IMAGE_BASE_RELOCATION*)((DWORD_PTR)baseRelocation + (DWORD_PTR)baseRelocation-&gt;SizeOfBlock);
} 
</code></pre>

