        return -1;
    }

    //get the mixer control info for the volume control
    int controlCount = mxl.cControls;
    MIXERCONTROLDETAILS mxcd = new MIXERCONTROLDETAILS();
    mxcd.cbStruct = Marshal.SizeOf(mxcd);
    mxcd.cChannels = 1;
    mxcd.dwControlID = 0;
    mxcd.cbDetails = Marshal.SizeOf(typeof(int));
    mxcd.paDetails = Marshal.AllocHGlobal(mxcd.cbDetails);

    for (int i = 0; i &lt; controlCount; i++)
    {
        MIXERCONTROL mc = new MIXERCONTROL();
        mc.cbStruct = Marshal.SizeOf(mc);
        mc.dwControlType = MIXERCONTROL_CONTROLTYPE_VOLUME;
        mc.cChannels = 1;
        mc.cMultipleItems = 0;
        mc.dwMinimum = 0;
        mc.dwMaximum = ushort.MaxValue;
        mc.cbDetails = 0;
