        if (result != 0)
        {
            Marshal.FreeHGlobal(mxcd.paDetails);
            mixerClose(hMixer);
            return -1;
        }

        mc.dwControlID = ((int*)mxcd.paDetails)[0];
        mxcd.dwControlID = mc.dwControlID;

        result = mixerGetLineControls(hMixer, ref mc, MIXER_GETLINECONTROLSF_ONEBYTYPE);
        if (result != 0)
        {
            Marshal.FreeHGlobal(mxcd.paDetails);
            mixerClose(hMixer);
            return -1;
        }

        if ((mc.dwControlType & MIXERCONTROL_CONTROLTYPE_VOLUME) == MIXERCONTROL_CONTROLTYPE_VOLUME)
        {
            mxcd.cbDetails = Marshal.SizeOf(typeof(int));
            mxcd.paDetails = Marshal.AllocHGlobal(mxcd.cbDetails);

            int volume = (newVolumeInPercent * ushort.MaxValue) / 100;
            ((int*)mxcd.paDetails)[0] = volume | (volume &lt;&lt; 16);

            result = mixerSetControlDetails(hMixer, ref mxcd, MIXER_SETCONTROLDETAILSF_VALUE);
            if (result != 0)
            {
                Marshal.FreeHGlobal(mxcd.paDetails);
                mixerClose(hMixer);
                return -1;
            }

            Marshal.FreeHGlobal(mxcd.paDetails);
            mixerClose(hMixer);
            return newVolumeInPercent;
        }
    }

    Marshal.FreeHGlobal(mxcd.paDetails);
    mixerClose(hMixer);
    return -1;
}

