Here's an example of how you can use GMock to set up a mock object for the <code>Member</code> class and verify that <code>member_method</code> is called on <code>parent_method</code</code> call:

<pre><code>#include &lt;gmock/gmock.h&gt;

class IMember
{
public:
    virtual ~IMember() {}
    virtual void member_method() = 0;
};

class MockMember : public IMember
{
public:
    MOCK_METHOD0(member_method, void());
};

class IParent
{
public:
    virtual ~IParent() {}
    virtual void parent_method() = 0;
};

class Parent : public IParent
{
public:
    Parent(IMember& member) : member_{member} {}
    void parent_method() override
    {
        member_.member_method();
    }
private:
    IMember& member_;
};

TEST(ParentTest, parent_method_calls_member_method)
{
    MockMember mock_member;
    EXPECT_CALL(mock_member, member_method());

    Parent parent{mock_member};
    parent.parent_method();
}</code></pre>

In this example, we define an interface <code>IMember</code> for the <code>Member</code> class and create a mock object <code>MockMember</code> that implements this interface. We also define an interface <code>IParent</code> for the <code>Parent</code> class.

In the <code>Parent</code> class, we pass an <code>IMember</code> reference to the constructor instead of creating a <code>Member</code> object directly. This allows us to pass either a real <code>Member</code> object or a mock object during testing.

