One possible solution to this problem is to use a dictionary to keep track of the occurrences of each element, and then iterate through the dictionary to build the output array. Here's an example implementation:

```swift
func splitEqualElements<T: Hashable>(array: [T]) -> [[T]] {
    // Create a dictionary to count the occurrences of each element
    var counts = [T: Int]()
    for element in array {
        counts[element, default: 0] += 1
    }

    // Create an array of arrays to hold the subsequences
    var subsequences = [[T]]()

    // Iterate through the dictionary and create subarrays
    for (element, count) in counts {
        let subarray = Array(repeating: element, count: count)
        subsequences.append(subarray)
    }

    return subsequences
}
```

