```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>

#define LINE_MAX 255
#define ARG_MAX  10

#define SH_PROMPT "next> "

int run_command(char *[]);
int getline(char *);
void parse_line(char *, char*[]);

int main(void)
{
    char line[LINE_MAX+1];
    char *argbuf[ARG_MAX+1]; // fix typo here
    int temp, status;

    do {
        printf(SH_PROMPT); fflush(stdout);

        if ((temp = getline(line)) != -1) {
            parse_line(line, argbuf);
            if (strcmp(argbuf[0], "exit") == 0) {
                break;
            }
            run_command(argbuf);
        }
    } while (temp != -1);

    printf("All done, bye-bye!\n");
    return 0;
}

int run_command(char *command[]) {
    pid_t child;
    int status;

    if ((child = fork()) == 0) {
        execvp(command[0], command);
        fprintf(stderr, "Child process could not do execvp.\n");
        exit(1);
    } else if (child == -1) {
        fprintf(stderr, "Fork failed - Use spoon. \n");
        exit(1);
    } else {
        waitpid(child, &status, 0);
        if (WIFEXITED(status)) {
            printf("Command %s has completed successfully\n", command[0]);
        } else {
            printf("Command %s has completed unsuccessfully\n", command[0]);
        }
        return 0;
    }
}

int getline(char *line) {
    int len;
    if (fgets(line, LINE_MAX + 1, stdin) == NULL)
        return -1;
    len = strlen(line);
    if (line[len-1] == '\n') {
        line[len-1] = '\0';
        len--;
    }
    return len;
}

void parse_line(char *line, char *argbuf[]) {
    int i = 0;
    const char *delim = " \t";
    char *p = strtok(line, delim);
    while (p != NULL && i < ARG_MAX) {
        argbuf[i++] = p;
        p = strtok(NULL, delim);
    }
    argbuf[i] = NULL;
}
```

