function splitArray($inputArray)
{
    $resultArray = array();
    $currentGroup = array();

    foreach ($inputArray as $value) {
        if ($value >= 1 && $value <= 5) {
            // value is between 1 and 5, add it to current group
            $currentGroup[] = $value;
