To select the images randomly to display them, you can use an array to store the image variables (art, art1, art2, art3) and then shuffle the array using the Fisher-Yates shuffle algorithm. Here is how you can modify your code to do that:

<pre><code>using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using UnityEngine.EventSystems;

public class NewBehaviourScript : MonoBehaviour
{
    public Image art;
    public Image art1;
    public Image art2;
    public Image art3;

    public string correctPath;
    public string[] incorrectPaths;

    void Start()
    {
        // Selection of correct letter
        int cl = Random.Range(1, 26);
        correctPath = "Capital Letters/correct_caps/" + cl;

        // Selection of incorrect letters
        int correctIndex = Random.Range(0, 4);
        int[] incorrectIndices = {0, 1, 2, 3};
        incorrectIndices[correctIndex] = -1; // mark the correct index as taken

        incorrectPaths = new string[3];
        for (int i = 0; i &lt; 3; i++)
        {
            int x = Random.Range(1, 5);
            while (x == (correctIndex+1) || System.Array.IndexOf(incorrectIndices, x) != -1)
            {
                x = Random.Range(1, 5);
            }
            incorrectIndices[i] = x;
            incorrectPaths[i] = "Capital Letters/" + cl + "/" + x;
        }

        // Shuffle the array of image variables
        Image[] images = {art, art1, art2, art3};
        ShuffleArray(images);

        // Display the images
        images[0].sprite = Resources.Load&lt;Sprite&gt;(correctPath) as Sprite; 
        images[1].sprite = Resources.Load&lt;Sprite&gt;(incorrectPaths[0]) as Sprite;
        images[2].sprite = Resources.Load&lt;Sprite&gt;(incorrectPaths[1]) as Sprite;
        images[3].sprite = Resources.Load&lt;Sprite&gt;(incorrectPaths[2]) as Sprite;
    }

    // Fisher-Yates shuffle algorithm
    void ShuffleArray&lt;T&gt;(T[] array)
    {
        for (int i = array.Length - 1; i &gt; 0; i--)
        {
            int j = Random.Range(0, i + 1);
            T temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
}</code></pre>

Note that I simplified your code by removing unnecessary variables and using arrays to store the paths and indices. I also replaced the while loops with do-while loops to guarantee that the the random values are different from the correct index and from each other.

