foreach ($rows as $row) {
  // If line starts with [Tone, create a new row in the database 
  if (substr($row, 0, 5) === '[Tone') {
    // Split the [ToneXX] line to get the ID of the tone
    $tone_id = substr($row, 0, -1);
    $tone_id = substr($tone_id, 1);

    // Create a new MySQL row with the tone ID
    $stmt = $con->prepare("INSERT INTO tones (id) VALUES (?)");
    $stmt->bind_param("s", $tone_id);
    $stmt->execute();
    $row_id = $stmt->insert_id;

    // Loop through the rest of the data and add to the MySQL row
    foreach ($rows as $row) {
      $row_data = explode(' = ', $row);
      if (count($row_data) == 2) {
        $attribute = trim($row_data[0]);
        $value = trim($row_data[1]);

        // Update the MySQL row with the attribute and value
        $stmt = $con->prepare("UPDATE tones SET $attribute = ? WHERE id = ?");
        $stmt->bind_param("si", $value, $row_id);
