    if granted {
        // User has granted permission
    } else {
        // User has denied permission
    }
}

// Save user preferences for push notifications
let defaults = UserDefaults.standard
defaults.set(true, forKey: "pushEnabled") // adjust "pushEnabled" according to your preference key
defaults.synchronize()

// Enable or disable push notifications
defaults.set(false, forKey: "pushEnabled")
defaults.synchronize()

// Clear all notifications in notification center
center.removeAllDeliveredNotifications()
```

