    }
}
```

2. In your app delegate or view controller, create a persistent instance of this accessory view and add it as a subview of the key window:

```
class AppDelegate: UIResponder, UIApplicationDelegate {

    var persistentAccessoryView: CustomKeyboardAccessoryView!

    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {

        // Create the persistent accessory view
        persistentAccessoryView = CustomKeyboardAccessoryView(frame: CGRect(x: 0, y: 0, width: UIScreen.main.bounds.width, height: 44))

