    "database/sql"
    _ "github.com/go-sql-driver/mysql"
)

var (
    ssdbPool *ssdb.Connectors
    redisPool *redis.Pool
    mysqlDB *sql.DB
)

func InitSSDB(ip string, port int, ...interface{}) error {
    ssdbPool, err := ssdb.ConnectPool(ip, port, ...)
    if err != nil {
        return err
    }
    return nil
}

func GetSSDB() *ssdb.Client {
    conn, err := ssdbPool.Get()
    if err != nil {
        // Handle error
    }
    return conn
}

func InitRedis(ip string, port int, ...interface{}) error {
    redisPool = &redis.Pool{
        MaxIdle:     80,
        MaxActive:   12000, // max number of connections
        IdleTimeout: 120 * time.Second,
        Dial: func() (redis.Conn, error) {
            c, err := redis.Dial("tcp", fmt.Sprintf("%s:%d", ip, port), ...)
            if err != nil {
                // Handle error
            }
            return c, err
        },
    }
    return nil
}

func GetRedis() redis.Conn {
    return redisPool.Get()
}

func InitMySQL(user, password, addr, database string) error {
    var err error
    mysqlDB, err = sql.Open("mysql", fmt.Sprintf("%s:%s@tcp(%s)/%s?charset=utf8mb4&parseTime=true", user, password, addr, database))

    if err != nil {
        return err
    }
    return nil
