One way to prevent `fgets` from blocking the loop is to use a separate thread for receiving data from the socket. Here is an example code:

```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 1234

int clientSocket = -1;

void *recv_thread(void *arg) {
    char buffer[1024];
    while (1) {
        ssize_t n = recv(clientSocket, buffer, sizeof(buffer), 0);
        if (n > 0) {
            buffer[n] = '\0';
            printf("%s", buffer);
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <server_ip>\n", argv[0]);
        exit(1);
    }

    clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket < 0) {
        perror("socket");
        exit(1);
    }

    fcntl(clientSocket, F_SETFL, O_NONBLOCK);

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(PORT);
    serverAddr.sin_addr.s_addr = inet_addr(argv[1]);

    if (connect(clientSocket, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) < 0) {
        if (errno != EINPROGRESS) {
            perror("connect");
            exit(1);
        }
    }

    pthread_t tid;
    if (pthread_create(&tid, NULL, recv_thread, NULL) != 0) {
        perror("pthread_create");
        exit(1);
    }

    char buffer[1024];
    while (1) {
        fgets(buffer, sizeof(buffer), stdin);
        send(clientSocket, buffer, strlen(buffer), 0);
    }

    return 0;
}
```

In this code, we create a separate thread `recv_thread` that blocks on `recv` to receive data from the socket. Meanwhile, the main thread uses `fgets` to read user input and sends it to the socket. Since the socket is non-blocking, `send` may return immediately and send only a part of the data. Therefore, we pass the length of the buffer to `send` instead of `sizeof(buffer)`. 

Note that we also check the return value of `connect` for `EINPROGRESS`, which indicates that the connection is in progress and will be completed asynchronously.

