    }

    public MyCustomDepartmentDeserializer(DepartmentRepository departmentRepository) {
        this.departmentRepository = departmentRepository;
    }

    @Override
    public Department deserialize(JsonParser jp, DeserializationContext ctxt) throws IOException, JsonProcessingException {
        // implementation
    }

    @Override
    public JsonDeserializer&lt;?&gt; createContextual(DeserializationContext ctxt, BeanProperty property) throws JsonMappingException {
        if (property != null) {
            // Get the annotation from the JsonProperty
            MyCustomDeserializerProperty myProperty = property.getAnnotation(MyCustomDeserializerProperty.class);
            if (myProperty != null) {
                // Create a new deserializer with the department repository dependency
                return new MyCustomDepartmentDeserializer(myProperty.departmentRepository());
