The command to get the uptime of the system in Linux(Ubuntu) is "sysinfo(&info);". This will store system information in the "info" structure from where we can extract the uptime using "info.uptime". 

To incorporate this in the server code, we can use the "sysinfo()" function after accepting the client's connection. The modified code is given below: 

```c
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/sysinfo.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

int main()
{
    int sock, connected, bytes_recieved , true = 1;  
    char send_data [1024] , recv_data[1024];    
    struct sockaddr_in server_addr,client_addr;    
    struct sysinfo info;  
    int sin_size;

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("Socket");
        exit(1);
    }

    if (setsockopt(sock,SOL_SOCKET,SO_REUSEADDR,&true,sizeof(int)) == -1) {
        perror("Setsockopt");
        exit(1);
    }

    server_addr.sin_family = AF_INET;         
    server_addr.sin_port = htons(1237);     
    server_addr.sin_addr.s_addr = INADDR_ANY; 
    bzero(&(server_addr.sin_zero),8); 

    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(struct sockaddr))== -1) {
        perror("Unable to bind");
        exit(1);
    }

    if (listen(sock, 5) == -1) {
        perror("Listen");
        exit(1);
    }

    printf ("\nTCPServer Waiting for client on port 1237");
    fflush(stdout);

    while(1) {  

        sin_size = sizeof(struct sockaddr_in);

        connected = accept(sock, (struct sockaddr *)&client_addr,&sin_size);

        printf("\n I got a connection from (%s , %d)",inet_ntoa(client_addr.sin_addr),ntohs(client_addr.sin_port));
        send(connected, "Hello this is a simple server", 100, 1);

        while (1) {
            printf("\n SEND (q or Q to quit) : ");
            fgets(send_data, sizeof(send_data), stdin);

            bytes_recieved = recv(connected,recv_data,1024,0);
            recv_data[bytes_recieved] = '\0';

            if (strcmp(recv_data , "u") == 0 || strcmp(recv_data , "U") == 0) {
                if (sysinfo(&info) == 0) {
                    snprintf(send_data, sizeof send_data, "Uptime: %ld seconds\n", info.uptime);
                } else {
                    snprintf(send_data, sizeof send_data, "Error getting uptime: %s\n", strerror(errno));
                }
                send(connected, send_data,strlen(send_data), 0);  
            }

        }  
        close(sock);
        return 0;
    }
}
``` 

In the server code, after accepting the client's connection, we can call "sysinfo(&info)" to get the system information. If the function returns 0, the system information is stored in the "info" structure which we can access using "info.uptime". If there is an error, we can handle it using the "strerror(errno)" function. 

We can then use the "snprintf()" function to format the output message and send it back to the client using the "send()" function.

